export function CustomCursor() {
  const dotRef = useRef(null);
  const ringRef = useRef(null);
  const pos = useRef({x:0,y:0});
  const ring = useRef({x:0,y:0});
  const [clicking, setClicking] = useState(false);
  const [hovering, setHovering] = useState(false);

  useEffect(() => {
    const move = e => {
      pos.current = {x: e.clientX, y: e.clientY};
      if(dotRef.current) {
        dotRef.current.style.transform = `translate(${e.clientX-4}px,${e.clientY-4}px)`;
      }
    };
    const tick = () => {
      ring.current.x += (pos.current.x - ring.current.x) * 0.12;
      ring.current.y += (pos.current.y - ring.current.y) * 0.12;
      if(ringRef.current) {
        ringRef.current.style.transform = `translate(${ring.current.x-16}px,${ring.current.y-16}px)`;
      }
      requestAnimationFrame(tick);
    };
    const raf = requestAnimationFrame(tick);
    const down = () => setClicking(true);
    const up   = () => setClicking(false);
    const over = e => setHovering(!!(e.target.closest('button,a,[data-hover]')));
    window.addEventListener('mousemove', move);
    window.addEventListener('mousedown', down);
    window.addEventListener('mouseup', up);
    window.addEventListener('mouseover', over);
    return () => { window.removeEventListener('mousemove',move); window.removeEventListener('mousedown',down); window.removeEventListener('mouseup',up); window.removeEventListener('mouseover',over); cancelAnimationFrame(raf); };
  },[]);

  return (
    <>
      <div ref={dotRef} style={{position:'fixed',top:0,left:0,width:8,height:8,borderRadius:'50%',background:hovering?'#ff3d6b':'#00f5c4',zIndex:99999,pointerEvents:'none',boxShadow:hovering?'0 0 10px #ff3d6b':'0 0 10px #00f5c4',transition:'background .15s,box-shadow .15s'}}/>
      <div ref={ringRef} style={{position:'fixed',top:0,left:0,width:32,height:32,borderRadius:'50%',border:`1.5px solid ${hovering?'rgba(255,61,107,.6)':'rgba(0,245,196,.5)'}`,zIndex:99998,pointerEvents:'none',transform:clicking?'scale(.75)':'scale(1)',transition:'border-color .15s,transform .1s'}}/>
    </>
  );
}

/* ─── PARTICLE BACKGROUND ────────────────────────────────── */
export function ParticleBackground() {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if(!canvas) return;
    const ctx = canvas.getContext('2d');
    let W = canvas.width = window.innerWidth;
    let H = canvas.height = window.innerHeight;
    const resize = () => { W = canvas.width = window.innerWidth; H = canvas.height = window.innerHeight; };
    window.addEventListener('resize', resize);
    const N = 55;
    const dots = Array.from({length:N}, () => ({
      x: Math.random()*W, y: Math.random()*H,
      vx: (Math.random()-.5)*.35, vy: (Math.random()-.5)*.35,
      r: Math.random()*1.5+.4,
      col: Math.random()<.5 ? '0,245,196' : (Math.random()<.5 ? '91,156,246' : '255,61,107'),
    }));
    let raf;
    const draw = () => {
      ctx.clearRect(0,0,W,H);
      dots.forEach(d => {
        d.x += d.vx; d.y += d.vy;
        if(d.x<0) d.x=W; if(d.x>W) d.x=0;
        if(d.y<0) d.y=H; if(d.y>H) d.y=0;
        ctx.beginPath();
        ctx.arc(d.x,d.y,d.r,0,Math.PI*2);
        ctx.fillStyle = `rgba(${d.col},.55)`;
        ctx.fill();
      });
      for(let i=0;i<N;i++) for(let j=i+1;j<N;j++) {
        const dx=dots[i].x-dots[j].x, dy=dots[i].y-dots[j].y;
        const dist=Math.sqrt(dx*dx+dy*dy);
        if(dist<120) {
          ctx.beginPath();
          ctx.moveTo(dots[i].x,dots[i].y);
          ctx.lineTo(dots[j].x,dots[j].y);
          ctx.strokeStyle=`rgba(0,245,196,${.12*(1-dist/120)})`;
          ctx.lineWidth=.6;
          ctx.stroke();
        }
      }
      raf = requestAnimationFrame(draw);
    };
    draw();
    return () => { cancelAnimationFrame(raf); window.removeEventListener('resize',resize); };
  },[]);
  return <canvas ref={canvasRef} style={{position:'fixed',inset:0,zIndex:0,pointerEvents:'none',opacity:.55}}/>;
}

/* ─── LOADING ────────────────────────────────────────────── */
export function LoadingScreen({ onDone }) {
  const [phase,setPhase]=useState(0);
  const [progress,setProgress]=useState(0);
  const [glitch,setGlitch]=useState(false);
  const [exiting,setExiting]=useState(false);
  const lines=[
    "INICIALIZANDO SISTEMA JDG v2.5...",
    "CARGANDO THE HEAD VOICE · UNITY...",
    "COMPILANDO METRO ZOMBIES · SHADERS...",
    "CONSTRUYENDO BIOASTRONOMÍA VR...",
    "CARGANDO PUZZLE GAME · MOBILE...",
    "TODOS LOS SISTEMAS LISTOS ✓",
  ];
  useEffect(()=>{
    let p=0;
    const iv=setInterval(()=>{p+=Math.random()*4+1;if(p>=100){p=100;clearInterval(iv);}setProgress(Math.min(Math.round(p),100));},60);
    const pts=[400,900,1500,2100,2700,3300].map((t,i)=>setTimeout(()=>setPhase(i+1),t));
    const gi=setInterval(()=>setGlitch(g=>!g),400);
    const gs=setTimeout(()=>clearInterval(gi),3500);
    const et=setTimeout(()=>{setExiting(true);setTimeout(onDone,700);},4600);
    return()=>{clearInterval(iv);pts.forEach(clearTimeout);clearInterval(gi);clearTimeout(gs);clearTimeout(et);};
  },[]);
  return(
    <div style={{position:"fixed",inset:0,zIndex:9999,background:"#020509",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",opacity:exiting?0:1,transform:exiting?"scale(1.05)":"scale(1)",transition:"opacity .7s,transform .8s cubic-bezier(.4,0,.2,1)",overflow:"hidden"}}>
      <style>{GLOBAL_CSS}</style>
      <div style={{position:"absolute",inset:0,backgroundImage:"linear-gradient(rgba(0,245,196,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(0,245,196,.04) 1px,transparent 1px)",backgroundSize:"48px 48px",animation:"gridPulse 3s ease-in-out infinite"}}/>
      <div style={{position:"absolute",left:0,right:0,height:2,background:"linear-gradient(90deg,transparent,rgba(0,245,196,.2),transparent)",animation:"scanDown 2.5s linear infinite"}}/>
      {[{top:20,left:20,borderTop:"2px solid #00f5c4",borderLeft:"2px solid #00f5c4"},{top:20,right:20,borderTop:"2px solid #00f5c4",borderRight:"2px solid #00f5c4"},{bottom:20,left:20,borderBottom:"2px solid #00f5c4",borderLeft:"2px solid #00f5c4"},{bottom:20,right:20,borderBottom:"2px solid #00f5c4",borderRight:"2px solid #00f5c4"}].map((s,i)=><div key={i} style={{position:"absolute",width:28,height:28,...s}}/>)}
      <div style={{textAlign:"center",position:"relative",zIndex:2,padding:"0 40px"}}>
        <div style={{fontFamily:"'Orbitron',monospace",fontWeight:900,fontSize:"clamp(56px,11vw,100px)",lineHeight:1,color:"#00f5c4",letterSpacing:-2,animation:glitch?"glitchX .12s ease":"none",textShadow:glitch?"4px 0 #ff3d6b,-4px 0 #5b9cf6,0 0 40px rgba(0,245,196,.6)":"0 0 60px rgba(0,245,196,.5),0 0 100px rgba(0,245,196,.2)",marginBottom:8}}>JDG</div>
        <div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:13,color:"#5a7a6a",letterSpacing:6,textTransform:"uppercase",marginBottom:60,animation:"fadeInUp .6s ease .3s both"}}>Juan David Guerrero Uchima</div>
        <div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:12,color:"#3a4a5a",textAlign:"left",width:"min(360px,80vw)",margin:"0 auto 40px",minHeight:108}}>
          {lines.slice(0,phase).map((line,i)=>(
            <div key={i} style={{marginBottom:7,animation:"fadeInUp .3s ease both",color:i===phase-1?"#00f5c4":"#2a4a3a"}}>
              <span style={{color:"#0a2a1a",marginRight:8}}>{">"}</span>{line}
              {i===phase-1&&phase<lines.length&&<span style={{animation:"blink .8s infinite",marginLeft:4}}>{"█"}</span>}
            </div>
          ))}
        </div>
        <div style={{width:"min(360px,80vw)",margin:"0 auto"}}>
          <div style={{display:"flex",justifyContent:"space-between",marginBottom:8}}>
            <span style={{fontFamily:"'Share Tech Mono',monospace",fontSize:11,color:"#2a4a3a",letterSpacing:2}}>LOADING</span>
            <span style={{fontFamily:"'Orbitron',monospace",fontSize:11,fontWeight:700,color:"#00f5c4"}}>{progress}%</span>
          </div>
          <div style={{height:2,background:"rgba(0,245,196,.08)",borderRadius:2,overflow:"hidden",position:"relative"}}>
            <div style={{height:"100%",width:`${progress}%`,background:"linear-gradient(90deg,#00f5c4,#5b9cf6,#00f5c4)",backgroundSize:"200%",borderRadius:2,transition:"width .1s linear",boxShadow:"0 0 15px rgba(0,245,196,.7)",animation:"shimmer 2s linear infinite"}}/>
          </div>
          <div style={{display:"flex",justifyContent:"space-between",marginTop:5}}>
            {Array.from({length:11}).map((_,i)=><div key={i} style={{width:1,height:3,background:progress>=i*10?"rgba(0,245,196,.7)":"rgba(255,255,255,.06)",transition:"background .2s"}}/>)}
          </div>
        </div>
        <div style={{marginTop:48,fontFamily:"'Share Tech Mono',monospace",fontSize:10,color:"#1a2a1a",letterSpacing:2,textTransform:"uppercase",animation:"fadeInUp .5s ease 1s both"}}>SYS // UNITY · REACT · VR · MOBILE · MEDELLÍN</div>
      </div>
    </div>
  );
}

