export function AnimatedSkillBar({ name, pct, color, delay=0 }) {
  const [w, setW] = useState(0);
  const ref = useRef(null);
  useEffect(() => {
    const obs = new IntersectionObserver(([e])=>{ if(e.isIntersecting){ setTimeout(()=>setW(pct),delay); } },{threshold:.2});
    if(ref.current) obs.observe(ref.current);
    return()=>obs.disconnect();
  },[pct,delay]);
  return (
    <div ref={ref} style={{display:"flex",alignItems:"center",gap:10,marginBottom:11}}>
      <span style={{fontSize:12,color:"#8090a8",minWidth:90}}>{name}</span>
      <div style={{flex:1,height:3,background:"rgba(255,255,255,.06)",borderRadius:2,overflow:"hidden"}}>
        <div style={{height:"100%",borderRadius:2,width:`${w}%`,background:`linear-gradient(90deg,${color},${color}88)`,transition:`width 1.2s cubic-bezier(.4,0,.2,1)`,boxShadow:`0 0 8px ${color}44`}}/>
      </div>
      <span style={{fontSize:10,color:"#445060",minWidth:30,textAlign:"right"}}>{pct}%</span>
    </div>
  );
}

