/* ══════════ SNAKE MINI-GAME ══════════ */
export const CELL = 18;
export const COLS_SN = 25;
export const ROWS_SN = 20;
export const DIRS = { ArrowUp:[0,-1], ArrowDown:[0,1], ArrowLeft:[-1,0], ArrowRight:[1,0] };

export function SnakeGame({ onClose, onWin }) {
  const canvasRef = useRef(null);
  const state = useRef({
    snake: [{x:12,y:10},{x:11,y:10},{x:10,y:10}],
    dir: [1,0], nextDir: [1,0],
    food: {x:18,y:8}, score:0, running:true, speed:150,
  });
  const rafRef = useRef(null);
  const lastRef = useRef(0);
  const [score, setScore] = useState(0);
  const [dead, setDead] = useState(false);
  const [won, setWon] = useState(false);

  const spawnFood = (snake) => {
    let f;
    do { f = {x:Math.floor(Math.random()*COLS_SN), y:Math.floor(Math.random()*ROWS_SN)}; }
    while (snake.some(s=>s.x===f.x&&s.y===f.y));
    return f;
  };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const s = state.current;

    const draw = (ts) => {
      if (!s.running) return;
      if (ts - lastRef.current < s.speed) { rafRef.current = requestAnimationFrame(draw); return; }
      lastRef.current = ts;
      s.dir = [...s.nextDir];

      // Move
      const head = { x: s.snake[0].x + s.dir[0], y: s.snake[0].y + s.dir[1] };
      // Wall wrap
      head.x = (head.x + COLS_SN) % COLS_SN;
      head.y = (head.y + ROWS_SN) % ROWS_SN;
      // Self collision
      if (s.snake.some(seg=>seg.x===head.x&&seg.y===head.y)) {
        s.running = false; setDead(true); return;
      }
      s.snake.unshift(head);
      // Eat food
      if (head.x===s.food.x && head.y===s.food.y) {
        s.score++; setScore(s.score);
        s.food = spawnFood(s.snake);
        s.speed = Math.max(60, s.speed - 4);
        if (s.score >= 15) { s.running=false; setWon(true); onWin && onWin(); return; }
      } else { s.snake.pop(); }

      // Draw
      ctx.fillStyle = "#06090f";
      ctx.fillRect(0,0,COLS_SN*CELL,ROWS_SN*CELL);

      // Grid
      ctx.strokeStyle = "rgba(0,245,196,0.04)";
      ctx.lineWidth = 0.5;
      for(let x=0;x<COLS_SN;x++) { ctx.beginPath();ctx.moveTo(x*CELL,0);ctx.lineTo(x*CELL,ROWS_SN*CELL);ctx.stroke(); }
      for(let y=0;y<ROWS_SN;y++) { ctx.beginPath();ctx.moveTo(0,y*CELL);ctx.lineTo(COLS_SN*CELL,y*CELL);ctx.stroke(); }

      // Snake
      s.snake.forEach((seg,i) => {
        const t = 1 - i/s.snake.length;
        ctx.fillStyle = i===0 ? "#00f5c4" : `rgba(0,${Math.floor(180*t+40)},${Math.floor(150*t+30)},${0.9*t+0.1})`;
        ctx.beginPath();
        ctx.roundRect(seg.x*CELL+1, seg.y*CELL+1, CELL-2, CELL-2, i===0?4:2);
        ctx.fill();
        if(i===0) {
          ctx.shadowColor="#00f5c4"; ctx.shadowBlur=10;
          ctx.fillStyle="#00f5c4";
          ctx.fill();
          ctx.shadowBlur=0;
        }
      });

      // Food (pulsing)
      const pulse = Math.sin(Date.now()/200)*0.3+0.7;
      ctx.shadowColor="#ff3d6b"; ctx.shadowBlur=12*pulse;
      ctx.fillStyle=`rgba(255,61,107,${pulse})`;
      ctx.beginPath();
      ctx.arc(s.food.x*CELL+CELL/2, s.food.y*CELL+CELL/2, CELL/2-2, 0, Math.PI*2);
      ctx.fill();
      ctx.shadowBlur=0;

      // Score HUD
      ctx.fillStyle="rgba(0,245,196,0.8)";
      ctx.font="bold 11px 'Orbitron',monospace";
      ctx.fillText(`SCORE: ${s.score}  |  TARGET: 15`, 8, 14);

      rafRef.current = requestAnimationFrame(draw);
    };
    rafRef.current = requestAnimationFrame(draw);

    const onKey = (e) => {
      if (DIRS[e.key]) {
        e.preventDefault();
        const [dx,dy] = DIRS[e.key];
        const [cx,cy] = s.dir;
        if (dx !== -cx || dy !== -cy) s.nextDir = [dx,dy];
      }
      if (e.key==="Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => { cancelAnimationFrame(rafRef.current); window.removeEventListener("keydown",onKey); };
  }, []);

  const restart = () => {
    const s = state.current;
    s.snake=[{x:12,y:10},{x:11,y:10},{x:10,y:10}];
    s.dir=[1,0]; s.nextDir=[1,0];
    s.food={x:18,y:8}; s.score=0; s.running=true; s.speed=150;
    setScore(0); setDead(false); setWon(false);
    lastRef.current=0;
    const canvas=canvasRef.current;
    if(canvas){const ctx=canvas.getContext("2d");requestAnimationFrame(function draw(ts){if(!s.running)return;const c=canvas.getContext("2d");c.fillStyle="#06090f";c.fillRect(0,0,COLS_SN*CELL,ROWS_SN*CELL);});}
    rafRef.current=requestAnimationFrame(function tick(ts){
      const ss=state.current;
      if(!ss.running)return;
      if(ts-lastRef.current<ss.speed){rafRef.current=requestAnimationFrame(tick);return;}
      lastRef.current=ts; ss.dir=[...ss.nextDir];
      const head={x:ss.snake[0].x+ss.dir[0],y:ss.snake[0].y+ss.dir[1]};
      head.x=(head.x+COLS_SN)%COLS_SN; head.y=(head.y+ROWS_SN)%ROWS_SN;
      if(ss.snake.some(seg=>seg.x===head.x&&seg.y===head.y)){ss.running=false;setDead(true);return;}
      ss.snake.unshift(head);
      if(head.x===ss.food.x&&head.y===ss.food.y){ss.score++;setScore(ss.score);ss.food=spawnFood(ss.snake);ss.speed=Math.max(60,ss.speed-4);if(ss.score>=15){ss.running=false;setWon(true);return;}}
      else ss.snake.pop();
      const ctx=canvas.getContext("2d");
      ctx.fillStyle="#06090f";ctx.fillRect(0,0,COLS_SN*CELL,ROWS_SN*CELL);
      ctx.strokeStyle="rgba(0,245,196,0.04)";ctx.lineWidth=0.5;
      for(let x=0;x<COLS_SN;x++){ctx.beginPath();ctx.moveTo(x*CELL,0);ctx.lineTo(x*CELL,ROWS_SN*CELL);ctx.stroke();}
      for(let y=0;y<ROWS_SN;y++){ctx.beginPath();ctx.moveTo(0,y*CELL);ctx.lineTo(COLS_SN*CELL,y*CELL);ctx.stroke();}
      ss.snake.forEach((seg,i)=>{const t=1-i/ss.snake.length;ctx.fillStyle=i===0?"#00f5c4":`rgba(0,${Math.floor(180*t+40)},${Math.floor(150*t+30)},${0.9*t+0.1})`;ctx.beginPath();ctx.roundRect(seg.x*CELL+1,seg.y*CELL+1,CELL-2,CELL-2,i===0?4:2);ctx.fill();});
      const pulse=Math.sin(Date.now()/200)*0.3+0.7;ctx.shadowColor="#ff3d6b";ctx.shadowBlur=12*pulse;ctx.fillStyle=`rgba(255,61,107,${pulse})`;ctx.beginPath();ctx.arc(ss.food.x*CELL+CELL/2,ss.food.y*CELL+CELL/2,CELL/2-2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
      ctx.fillStyle="rgba(0,245,196,0.8)";ctx.font="bold 11px 'Orbitron',monospace";ctx.fillText(`SCORE: ${ss.score}  |  TARGET: 15`,8,14);
      rafRef.current=requestAnimationFrame(tick);
    });
  };

  const overlay = dead || won;
  return (
    <div style={{position:"fixed",inset:0,zIndex:9000,background:"rgba(0,0,0,0.92)",display:"flex",alignItems:"center",justifyContent:"center",flexDirection:"column",animation:"fadeIn .3s ease"}}>
      <div style={{position:"relative"}}>
        {/* Header */}
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10,padding:"0 4px"}}>
          <div style={{fontFamily:"'Orbitron',monospace",fontSize:12,fontWeight:700,color:"#00f5c4",letterSpacing:3}}>
            🐍 SNAKE · JDG EDITION
          </div>
          <div style={{display:"flex",gap:10,alignItems:"center"}}>
            <span style={{fontFamily:"'Share Tech Mono',monospace",fontSize:11,color:"#3a5060"}}>ESC para salir · Flechas para moverse</span>
            <button onClick={onClose} style={{fontFamily:"'Orbitron',monospace",fontSize:9,color:"#ff3d6b",background:"rgba(255,61,107,.1)",border:"1px solid rgba(255,61,107,.3)",borderRadius:3,padding:"4px 10px",cursor:"none"}}>✕ CERRAR</button>
          </div>
        </div>

        {/* Canvas */}
        <div style={{position:"relative",border:"1px solid rgba(0,245,196,.3)",borderRadius:6,overflow:"hidden",boxShadow:"0 0 40px rgba(0,245,196,.15)"}}>
          <canvas ref={canvasRef} width={COLS_SN*CELL} height={ROWS_SN*CELL}/>

          {/* Overlay: dead or won */}
          {overlay && (
            <div style={{position:"absolute",inset:0,background:"rgba(6,9,15,.92)",display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:14}}>
              <div style={{fontFamily:"'Orbitron',monospace",fontSize:won?28:22,fontWeight:900,
                color:won?"#00f5c4":"#ff3d6b",
                textShadow:won?"0 0 30px rgba(0,245,196,.6)":"0 0 30px rgba(255,61,107,.6)"}}>
                {won ? "🏆 ¡GANASTE!" : "💀 GAME OVER"}
              </div>
              <div style={{fontFamily:"'Share Tech Mono',monospace",fontSize:14,color:"#6a7a90"}}>
                Score: <span style={{color:"#00f5c4",fontWeight:700}}>{score}</span> / 15
              </div>
              {won && <div style={{fontFamily:"'Orbitron',monospace",fontSize:10,color:"#ffd060",letterSpacing:2}}>ACHIEVEMENT DESBLOQUEADO 🏅</div>}
              <div style={{display:"flex",gap:10,marginTop:8}}>
                <button onClick={restart} style={{fontFamily:"'Orbitron',monospace",fontSize:10,fontWeight:700,letterSpacing:2,padding:"10px 22px",borderRadius:3,cursor:"none",border:"none",background:"#00f5c4",color:"#020810"}}>↺ REINTENTAR</button>
                <button onClick={onClose} style={{fontFamily:"'Orbitron',monospace",fontSize:10,fontWeight:700,letterSpacing:2,padding:"10px 22px",borderRadius:3,cursor:"none",border:"1px solid rgba(0,245,196,.3)",background:"transparent",color:"#00f5c4"}}>SALIR</button>
              </div>
            </div>
          )}
        </div>

        {/* Mobile controls hint */}
        <div style={{marginTop:10,display:"flex",justifyContent:"center",gap:8}}>
          {[["↑","ArrowUp"],["↓","ArrowDown"],["←","ArrowLeft"],["→","ArrowRight"]].map(([lbl,key])=>(
            <button key={key} onMouseDown={()=>{const e=new KeyboardEvent("keydown",{key,bubbles:true});window.dispatchEvent(e);}}
              style={{width:36,height:36,borderRadius:4,background:"rgba(0,245,196,.08)",border:"1px solid rgba(0,245,196,.2)",color:"#00f5c4",fontSize:16,cursor:"none",display:"flex",alignItems:"center",justifyContent:"center"}}>
              {lbl}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ══════════ SNAKE LAUNCHER ══════════ */
export function SnakeLauncher({ onAchieve }) {
  const [open, setOpen] = useState(false);
  useEffect(() => {
    const seq = [];
    const CODE = ["s","n","a","k","e"];
    const onKey = (e) => {
      seq.push(e.key.toLowerCase());
      if (seq.length > 5) seq.shift();
      if (seq.join("") === CODE.join("")) { setOpen(true); onAchieve("snake_found"); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);
  if (!open) return null;
  return <SnakeGame onClose={()=>setOpen(false)} onWin={()=>onAchieve("snake_win")}/>;
}


